css:
:root {
  --legend-background: transparent;
  --legend-text: #6C8193;

  --legend-material: #0A638F;
  --legend-steam: #930606;
  --legend-condensate: #4E4E4E;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.legend-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: var(--legend-background);
  pointer-events: none;
}

.legend-svg {
  display: block;
  width: 100%;
  height: 100%;

  font-family: "Segoe UI", Arial, sans-serif;
  shape-rendering: geometricPrecision;
}

.legend-line {
  fill: none;
  stroke-width: 7;
  stroke-linecap: butt;
}

.legend-material {
  stroke: var(--legend-material);
}

.legend-steam {
  stroke: var(--legend-steam);
}

.legend-condensate {
  stroke: var(--legend-condensate);
}

.legend-text {
  fill: var(--legend-text);
  font-size: 32px;
  font-weight: 400;
  dominant-baseline: middle;
}
